mapper.select:
SELECT r.id AS id, r.receipt_no AS receiptNo, r.order_id AS orderId, o.order_name AS orderName, r.amount AS amount, r.receipt_time AS receiptTime, r.type AS type, r.status AS status, r.remark AS remark, r.create_time AS createTime FROM ad_receipt r LEFT JOIN ad_order o ON o.id = r.order_id AND o.deleted = 0 WHERE r.organization_id = #{request.organizationId} AND r.deleted = 0
AND r.order_id = #{request.orderId}
AND r.status = #{request.status}
AND r.type = #{request.type}
AND (r.receipt_no LIKE CONCAT('%', #{request.keyword}, '%') OR o.order_no LIKE CONCAT('%', #{request.keyword}, '%'))
